{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Testosterone, a steroid sharing the 3-keto-4-ene A-ring and similar lipophilic scaffold, has absolute oral bioavailability of only 3.66 ± 2.45% in women, demonstrating extensive first-pass inactivation of this steroid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Progesterone, with the same 3-keto-4-ene A-ring, has poor oral bioavailability (often <10%) due to intestinal/hepatic metabolism and low solubility, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Medroxyprogesterone acetate, another 3-keto-4-ene steroid, has low oral bioavailability (<10%), reinforcing the pattern that unmodified steroid ketones undergo extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ethinylestradiol has 25–65% oral bioavailability, but this is enabled by the 17α-ethynyl group and phenolic 3-OH; the query lacks these protective/polar features, so this high-F evidence does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C45"],
      "claim": "DHEA sulfate was projected at 40–70% oral bioavailability, but it is a 3β-sulfate 5-ene steroid, structurally distant from the 4-hydroxy-3-keto-4-ene query; low transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "17-Methyltestosterone has good oral bioavailability due to 17α-methyl protection of the 17-OH; the query has a 17-ketone and no such protection, so this high-F result is not applicable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C26"],
      "claim": "Norethisterone has ~64% oral bioavailability, but its high F depends on the 17α-ethynyl group; the query lacks this metabolic protection.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low oral bioavailability (<20%). The closest relevant steroid analogues with the same 3-keto-4-ene A-ring—testosterone and progesterone—show low absolute oral bioavailability due to extensive first-pass metabolism and solubility limitations. High-bioavailability analogues such as ethinylestradiol, 17-methyltestosterone, and norethisterone owe their oral activity to protective 17α-substituents absent in the query, which is a 4-hydroxyandrostenedione with a 17-ketone.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for formestane/4-hydroxyandrostenedione was provided.",
    "Uncertainty remains about the extent of 4-hydroxy conjugation and whether solubility-limited absorption further reduces F.",
    "Human pharmacokinetic data for the exact query would be needed to confirm the extrapolation from testosterone/progesterone."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

